	PlanCephCluster(context.Context, *PlanCephClusterRequest) (*PlanCephClusterResponse, error)
	CreateCephCluster(context.Context, *CreateCephClusterRequest) (*CreateCephClusterResponse, error)
	GetCephCluster(context.Context, *GetCephClusterRequest) (*GetCephClusterResponse, error)
	ListCephClusters(context.Context, *ListCephClustersRequest) (*ListCephClustersResponse, error)
	DeleteCephCluster(context.Context, *DeleteCephClusterRequest) (*DeleteCephClusterResponse, error)
	// On-demand capacity from a live member (`ceph df`). Read-only.
	GetCephClusterCapacity(context.Context, *GetCephClusterCapacityRequest) (*GetCephClusterCapacityResponse, error)
	// Upstream Ceph Manager Dashboard login material stored by the controller.
	// Ceph itself keeps only a password hash, so plaintext is served from kcore.
	GetCephDashboardCredentials(context.Context, *GetCephDashboardCredentialsRequest) (*GetCephDashboardCredentialsResponse, error)
	SetCephDashboardCredentials(context.Context, *SetCephDashboardCredentialsRequest) (*SetCephDashboardCredentialsResponse, error)
	// SharedFilesystem (CephFS) — cluster-scoped POSIX file service on Ceph.
	CreateSharedFilesystem(context.Context, *CreateSharedFilesystemRequest) (*CreateSharedFilesystemResponse, error)
	GetSharedFilesystem(context.Context, *GetSharedFilesystemRequest) (*GetSharedFilesystemResponse, error)
	ListSharedFilesystems(context.Context, *ListSharedFilesystemsRequest) (*ListSharedFilesystemsResponse, error)
	DeleteSharedFilesystem(context.Context, *DeleteSharedFilesystemRequest) (*DeleteSharedFilesystemResponse, error)
	// Ingress gateway (Caddy + Coraza WAF). Specs travel as the canonical
	// camelCase JSON documents; the controller parses them strictly.
	PlanIngress(context.Context, *PlanIngressRequest) (*PlanIngressResponse, error)
	CreateIngressGateway(context.Context, *CreateIngressGatewayRequest) (*CreateIngressGatewayResponse, error)
	GetIngressGateway(context.Context, *GetIngressGatewayRequest) (*GetIngressGatewayResponse, error)
	ListIngressGateways(context.Context, *ListIngressGatewaysRequest) (*ListIngressGatewaysResponse, error)
	DeleteIngressGateway(context.Context, *DeleteIngressGatewayRequest) (*DeleteIngressGatewayResponse, error)
	CreateIngressRoute(context.Context, *CreateIngressRouteRequest) (*CreateIngressRouteResponse, error)
	GetIngressRoute(context.Context, *GetIngressRouteRequest) (*GetIngressRouteResponse, error)
	ListIngressRoutes(context.Context, *ListIngressRoutesRequest) (*ListIngressRoutesResponse, error)
	DeleteIngressRoute(context.Context, *DeleteIngressRouteRequest) (*DeleteIngressRouteResponse, error)
	SetIngressRouteWafMode(context.Context, *SetIngressRouteWafModeRequest) (*SetIngressRouteWafModeResponse, error)
	CreateWafPolicy(context.Context, *CreateWafPolicyRequest) (*CreateWafPolicyResponse, error)
	GetWafPolicy(context.Context, *GetWafPolicyRequest) (*GetWafPolicyResponse, error)
	ListWafPolicies(context.Context, *ListWafPoliciesRequest) (*ListWafPoliciesResponse, error)
	DeleteWafPolicy(context.Context, *DeleteWafPolicyRequest) (*DeleteWafPolicyResponse, error)
	ListWafEvents(context.Context, *ListWafEventsRequest) (*ListWafEventsResponse, error)
	// Writes a secret file (for example dns.env) on every node of a gateway.
	SetIngressSecret(context.Context, *SetIngressSecretRequest) (*SetIngressSecretResponse, error)
	// Node agent -> controller: batches of Coraza audit events.
	ReportWafEvents(context.Context, *ReportWafEventsRequest) (*ReportWafEventsResponse, error)
	// ObjectStore (RGW) — S3-compatible object storage on Ceph.
	CreateObjectStore(context.Context, *CreateObjectStoreRequest) (*CreateObjectStoreResponse, error)
	GetObjectStore(context.Context, *GetObjectStoreRequest) (*GetObjectStoreResponse, error)
	ListObjectStores(context.Context, *ListObjectStoresRequest) (*ListObjectStoresResponse, error)
	DeleteObjectStore(context.Context, *DeleteObjectStoreRequest) (*DeleteObjectStoreResponse, error)
	CreateObjectUser(context.Context, *CreateObjectUserRequest) (*CreateObjectUserResponse, error)
	DeleteObjectUser(context.Context, *DeleteObjectUserRequest) (*DeleteObjectUserResponse, error)
	// RBAC: operators identified by client cert CN=kctl:<name>. Legacy CN=kctl is bootstrap-only.
	CreateOperator(context.Context, *CreateOperatorRequest) (*CreateOperatorResponse, error)
	DeleteOperator(context.Context, *DeleteOperatorRequest) (*DeleteOperatorResponse, error)
	ListOperators(context.Context, *ListOperatorsRequest) (*ListOperatorsResponse, error)
	GetOperator(context.Context, *GetOperatorRequest) (*GetOperatorResponse, error)
	GrantOperatorRole(context.Context, *GrantOperatorRoleRequest) (*GrantOperatorRoleResponse, error)
	RevokeOperatorRole(context.Context, *RevokeOperatorRoleRequest) (*RevokeOperatorRoleResponse, error)
	IssueOperatorCert(context.Context, *IssueOperatorCertRequest) (*IssueOperatorCertResponse, error)
