	PlanSlurmCluster(context.Context, *PlanSlurmClusterRequest) (*PlanSlurmClusterResponse, error)
	CreateSlurmCluster(context.Context, *CreateSlurmClusterRequest) (*CreateSlurmClusterResponse, error)
	GetSlurmCluster(context.Context, *GetSlurmClusterRequest) (*GetSlurmClusterResponse, error)
